{
  "name": "email-os-ui",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "description": "Keyboard-first fixture and read-only Gmail inbox UI. Browser preview is synthetic and in-memory only.",
  "scripts": {
    "dev": "vite",
    "build": "vue-tsc --noEmit -p tsconfig.json && vite build",
    "test": "vitest run",
    "typecheck": "vue-tsc --noEmit -p tsconfig.json",
    "tauri": "tauri"
  },
  "dependencies": {
    "@tauri-apps/api": "2.3.0",
    "vue": "3.5.13"
  },
  "devDependencies": {
    "@vitejs/plugin-vue": "5.2.1",
    "@vue/test-utils": "2.4.6",
    "jsdom": "26.0.0",
    "typescript": "5.7.3",
    "vite": "6.0.11",
    "vitest": "3.0.5",
    "vue-tsc": "2.2.0",
    "@tauri-apps/cli": "2.3.0"
  },
  "packageManager": "pnpm@10.18.0",
  "pnpm": {
    "onlyBuiltDependencies": [
      "esbuild"
    ]
  }
}

/** Core read models are authoritative; events only request another snapshot. */
import { computed, onScopeDispose, ref, type ComputedRef, type Ref } from 'vue';
import type {
  AccountStatus,
  Conversation,
  ConversationRef,
  InboxSnapshot,
  MailClient,
  MailError,
  MailMode,
  OperationReceipt,
} from '../lib/ipc/client';
import { toMailError } from '../lib/ipc/client';

export type ListState = 'loading' | 'ready' | 'error';
export type DetailState = 'idle' | 'loading' | 'ready' | 'error';
export type AccountState = 'loading' | 'ready' | 'error';
export type AccountAction = 'connect' | 'disconnect' | 'sync' | 'enable-actions' | 'cancel-upgrade';
export type ConversationSummaryLike = InboxSnapshot['conversations'][number];
export type OperationSummaryLike = InboxSnapshot['activity'][number];

export function sameConversation(a: ConversationRef | null, b: ConversationRef | null): boolean {
  return a !== null && b !== null && a.accountId === b.accountId && a.conversationId === b.conversationId;
}

export interface Mailbox {
  conversations: Ref<ConversationSummaryLike[]>;
  activity: Ref<OperationSummaryLike[]>;
  listState: Ref<ListState>;
  listError: Ref<MailError | null>;
  selectedIndex: Ref<number>;
  selectedSummary: Ref<ConversationSummaryLike | null>;
  openRef: Ref<ConversationRef | null>;
  conversation: Ref<Conversation | null>;
  detailState: Ref<DetailState>;
  detailError: Ref<MailError | null>;
  lastCommandError: Ref<MailError | null>;
  inFlightCommandRef: Ref<ConversationRef | null>;
  /** Authoritative account/mode status; `null` until the first status read lands. */
  accountStatus: Ref<AccountStatus | null>;
  accountState: Ref<AccountState>;
  accountError: Ref<MailError | null>;
  accountBusy: Ref<AccountAction | null>;
  /** Mode from the last accepted status; `null` while unknown (UI must fail closed). */
  mode: ComputedRef<MailMode | null>;
  isGmail: ComputedRef<boolean>;
  ready: Promise<void>;
  refresh(): Promise<void>;
  connectAccount(): Promise<void>;
  disconnectAccount(): Promise<void>;
  requestSync(): Promise<void>;
  moveSelection(delta: number): void;
  selectIndex(index: number): void;
  openConversationByRef(ref: ConversationRef): Promise<void>;
  openSelected(): Promise<void>;
  closeReader(): void;
  setArchived(target: ConversationRef, archived: boolean): Promise<OperationReceipt | null>;
  setRead(target: ConversationRef, read: boolean): Promise<OperationReceipt | null>;
  retryOperation(operationId: string): Promise<OperationReceipt | null>;
  enableMailboxActions(): Promise<void>;
  cancelMailboxActionUpgrade(): Promise<void>;
  archiveSelected(): Promise<void>;
}

export function useMailbox(client: MailClient): Mailbox {
  const conversations = ref<ConversationSummaryLike[]>([]);
  const activity = ref<OperationSummaryLike[]>([]);
  const listState = ref<ListState>('loading');
  const listError = ref<MailError | null>(null);
  const selectedIndex = ref(0);
  const openRef = ref<ConversationRef | null>(null);
  const conversation = ref<Conversation | null>(null);
  const detailState = ref<DetailState>('idle');
  const detailError = ref<MailError | null>(null);
  const lastCommandError = ref<MailError | null>(null);
  const inFlightCommandRef = ref<ConversationRef | null>(null);
  const accountStatus = ref<AccountStatus | null>(null);
  const accountState = ref<AccountState>('loading');
  const accountError = ref<MailError | null>(null);
  const accountBusy = ref<AccountAction | null>(null);

  let listToken = 0;
  let detailToken = 0;
  let commandToken = 0;
  let mailboxSessionToken = 0;
  let statusToken = 0;
  let detached = false;
  let unsubscribe: (() => void) | null = null;
  let subscriptionAttempt: Promise<void> | null = null;

  async function ensureSubscribed(): Promise<void> {
    if (unsubscribe || detached) return;
    if (!subscriptionAttempt) {
      // Share an in-flight attempt; a failed attempt is retried on Retry/focus/online.
      subscriptionAttempt = Promise.resolve()
        .then(() => client.subscribe(() => { void refresh(); }))
        .then((unsub) => {
          if (detached) unsub();
          else unsubscribe = unsub;
        })
        .finally(() => { subscriptionAttempt = null; });
    }
    await subscriptionAttempt;
  }

  async function refreshList(token: number): Promise<void> {
    const snap = await client.listConversations();
    if (detached || token !== listToken) return;
    // Preserve identity, not position, when a failed archive restores an earlier row.
    const selected = conversations.value[selectedIndex.value]?.ref ?? null;
    const retainedIndex = snap.conversations.findIndex((row) => sameConversation(row.ref, selected));
    conversations.value = snap.conversations;
    activity.value = snap.activity;
    selectedIndex.value = retainedIndex >= 0
      ? retainedIndex
      : Math.min(selectedIndex.value, Math.max(0, snap.conversations.length - 1));
    listError.value = null;
    listState.value = 'ready';
  }

  /** Status failures never reject: the UI gate renders them and stays fail-closed. */
  async function refreshStatus(token: number): Promise<void> {
    try {
      const status = await client.getAccountStatus();
      if (detached || token !== statusToken) return;
      accountStatus.value = status;
      accountError.value = null;
      accountState.value = 'ready';
    } catch (raw) {
      if (detached || token !== statusToken) return;
      accountError.value = toMailError(raw);
      accountState.value = 'error';
    }
  }

  async function refresh(): Promise<void> {
    if (detached) return;
    const token = ++listToken;
    try {
      // Subscription-before-read: events are registered before any status/list/detail
      // read so a change occurring mid-refresh cannot be lost. A successful list alone
      // must not hide a broken change subscription.
      await ensureSubscribed();
      if (detached) return;
      // Status failures are handled inside refreshStatus (the UI gate renders them
      // fail-closed); list/detail failures reject into the catch below.
      await Promise.all([
        refreshStatus(++statusToken),
        refreshList(token),
        openRef.value ? loadDetail(openRef.value, true) : Promise.resolve(),
      ]);
    } catch (raw) {
      if (detached || token !== listToken) return;
      listError.value = toMailError(raw);
      listState.value = 'error';
    }
  }

  async function loadDetail(target: ConversationRef, background = false): Promise<void> {
    if (detached) return;
    const token = ++detailToken;
    if (!background) {
      // New object records explicit navigation independently of background refreshes.
      openRef.value = { ...target };
      conversation.value = null;
      detailState.value = 'loading';
      detailError.value = null;
    }
    try {
      const conv = await client.getConversation(target);
      if (detached || token !== detailToken || !sameConversation(openRef.value, target)) return;
      conversation.value = conv;
      detailState.value = 'ready';
      detailError.value = null;
    } catch (raw) {
      if (detached || token !== detailToken || !sameConversation(openRef.value, target)) return;
      detailError.value = toMailError(raw);
      detailState.value = 'error';
      conversation.value = null;
    }
  }

  function moveSelection(delta: number): void {
    if (conversations.value.length === 0) return;
    selectedIndex.value = Math.min(conversations.value.length - 1, Math.max(0, selectedIndex.value + delta));
  }

  function selectIndex(index: number): void {
    if (index >= 0 && index < conversations.value.length) selectedIndex.value = index;
  }

  async function openConversationByRef(target: ConversationRef): Promise<void> {
    await loadDetail(target);
  }

  async function openSelected(): Promise<void> {
    const summary = conversations.value[selectedIndex.value];
    if (summary) await loadDetail(summary.ref);
  }

  function closeReader(): void {
    detailToken += 1;
    openRef.value = null;
    conversation.value = null;
    detailState.value = 'idle';
    detailError.value = null;
  }

  async function connectAccount(): Promise<void> {
    if (accountBusy.value) return;
    accountBusy.value = 'connect';
    // Mirror core: connecting flips the connection optimistically; a failure is
    // corrected by the status refetch below.
    if (accountStatus.value) {
      accountStatus.value = { ...accountStatus.value, connection: 'authenticating' };
    }
    try {
      await client.connectAccount();
      if (!detached) await refresh();
    } catch (raw) {
      if (!detached) {
        lastCommandError.value = toMailError(raw);
        await refreshStatus(++statusToken);
      }
    } finally {
      if (!detached) accountBusy.value = null;
    }
  }

  async function disconnectAccount(): Promise<void> {
    if (accountBusy.value) return;
    accountBusy.value = 'disconnect';
    try {
      // Resolves only after core deleted credentials and cleared local data.
      await client.disconnectAccount();
    } catch (raw) {
      if (!detached) lastCommandError.value = toMailError(raw);
      return;
    } finally {
      if (!detached) accountBusy.value = null;
    }
    if (detached) return;
    // Drop every cached surface immediately and invalidate in-flight reads so stale
    // responses cannot repopulate the UI after a disconnect.
    closeReader();
    listToken += 1;
    detailToken += 1;
    commandToken += 1;
    mailboxSessionToken += 1;
    inFlightCommandRef.value = null;
    conversations.value = [];
    activity.value = [];
    selectedIndex.value = 0;
    if (accountStatus.value) {
      const sync = accountStatus.value.sync;
      accountStatus.value = {
        ...accountStatus.value,
        connection: 'disconnected',
        account: null,
        sync: { ...sync, state: 'idle', error: null, lastSyncedAt: null, cachedConversations: 0, initialSyncComplete: false },
      };
    }
    await refresh();
  }

  async function requestSync(): Promise<void> {
    if (accountBusy.value) return;
    accountBusy.value = 'sync';
    try {
      // Acceptance, not completion; progress arrives via status changes/events.
      await client.requestSync();
      if (!detached) await refresh();
    } catch (raw) {
      if (!detached) lastCommandError.value = toMailError(raw);
    } finally {
      if (!detached) accountBusy.value = null;
    }
  }

  function mutationsAllowed(): boolean {
    if (accountState.value !== 'ready' || !accountStatus.value) {
      lastCommandError.value = { kind: 'invalid_request', field: 'accountStatus' };
      return false;
    }
    if (accountStatus.value.mode === 'gmail' && accountStatus.value.mutationAccess !== 'enabled') {
      lastCommandError.value = { kind: 'read_only' };
      return false;
    }
    return true;
  }

  async function submitMutation(
    send: (requestId: string) => Promise<OperationReceipt>,
    target: ConversationRef | null,
  ): Promise<OperationReceipt | null> {
    if (!mutationsAllowed()) return null;
    const token = ++commandToken;
    const sessionToken = mailboxSessionToken;
    inFlightCommandRef.value = target ? { ...target } : null;
    try {
      const receipt = await send(crypto.randomUUID());
      if (detached || sessionToken !== mailboxSessionToken) return receipt;
      if (token === commandToken) lastCommandError.value = null;
      // A successful receipt is authoritative acceptance even if a newer
      // command owns the error slot. Events are best-effort, so refresh this
      // account session rather than dropping the older accepted operation.
      await refresh();
      return receipt;
    } catch (raw) {
      if (!detached && sessionToken === mailboxSessionToken && token === commandToken) {
        lastCommandError.value = toMailError(raw);
      }
      return null;
    } finally {
      if (!detached && sessionToken === mailboxSessionToken && token === commandToken) {
        inFlightCommandRef.value = null;
      }
    }
  }

  async function setArchived(target: ConversationRef, archived: boolean): Promise<OperationReceipt | null> {
    return submitMutation(
      (requestId) => client.setArchived({ conversation: { ...target }, archived, requestId }),
      target,
    );
  }

  async function setRead(target: ConversationRef, read: boolean): Promise<OperationReceipt | null> {
    if (accountStatus.value?.mode !== 'gmail') {
      lastCommandError.value = { kind: 'read_only' };
      return null;
    }
    return submitMutation(
      (requestId) => client.setRead({ conversation: { ...target }, read, requestId }),
      target,
    );
  }

  async function retryOperation(operationId: string): Promise<OperationReceipt | null> {
    if (mode.value !== 'gmail') {
      lastCommandError.value = { kind: 'invalid_request', field: 'mode' };
      return null;
    }
    return submitMutation(
      (requestId) => client.retryOperation({ operationId, requestId }),
      null,
    );
  }

  async function enableMailboxActions(): Promise<void> {
    if (accountBusy.value || accountState.value !== 'ready' || accountStatus.value?.mode !== 'gmail' || accountStatus.value.mutationAccess === 'enabled') return;
    accountBusy.value = 'enable-actions';
    lastCommandError.value = null;
    try {
      // This command only accepts/enqueues an explicit OAuth upgrade. Enabled state
      // comes exclusively from a later authoritative account-status read.
      await client.enableMailboxActions();
      if (!detached) await refreshStatus(++statusToken);
    } catch (raw) {
      if (!detached) {
        lastCommandError.value = toMailError(raw);
        await refreshStatus(++statusToken);
      }
    } finally {
      if (!detached) accountBusy.value = null;
    }
  }

  async function cancelMailboxActionUpgrade(): Promise<void> {
    if (accountBusy.value || accountState.value !== 'ready' || accountStatus.value?.mutationAccess !== 'upgrading') return;
    accountBusy.value = 'cancel-upgrade';
    lastCommandError.value = null;
    try {
      await client.cancelMailboxActionUpgrade();
      if (!detached) await refreshStatus(++statusToken);
    } catch (raw) {
      if (!detached) {
        lastCommandError.value = toMailError(raw);
        await refreshStatus(++statusToken);
      }
    } finally {
      if (!detached) accountBusy.value = null;
    }
  }

  async function archiveSelected(): Promise<void> {
    const summary = conversations.value[selectedIndex.value];
    if (summary) await setArchived(summary.ref, true);
  }

  const ready = refresh();
  const onWindowFocus = (): void => { void refresh(); };
  const onReconnect = (): void => { void refresh(); };
  window.addEventListener('focus', onWindowFocus);
  window.addEventListener('online', onReconnect);

  onScopeDispose(() => {
    detached = true;
    listToken += 1;
    detailToken += 1;
    unsubscribe?.();
    unsubscribe = null;
    window.removeEventListener('focus', onWindowFocus);
    window.removeEventListener('online', onReconnect);
  });

  const selectedSummary = computed(() => conversations.value[selectedIndex.value] ?? null);
  const mode = computed<MailMode | null>(() => accountStatus.value?.mode ?? null);
  const isGmail = computed(() => mode.value === 'gmail');
  return {
    conversations, activity, listState, listError, selectedIndex, selectedSummary,
    openRef, conversation, detailState, detailError, lastCommandError,
    inFlightCommandRef, ready, refresh, moveSelection, selectIndex,
    openConversationByRef, openSelected, closeReader, setArchived, setRead, retryOperation,
    enableMailboxActions, cancelMailboxActionUpgrade, archiveSelected,
    accountStatus, accountState, accountError, accountBusy, mode, isGmail,
    connectAccount, disconnectAccount, requestSync,
  };
}

//! Rust-owned wire DTOs. CamelCase JSON fields, snake_case enum
//! discriminants, strings for IDs and ISO-8601 UTC timestamps, `null` for
//! absent optionals. The generated TypeScript contract lives in
//! `src/bin/generate-types.rs`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// Stable reference to one conversation on one account.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct ConversationRef {
    pub account_id: String,
    pub conversation_id: String,
}

/// One mail participant.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct Address {
    /// Absent display name serializes as `null`.
    pub display_name: Option<String>,
    pub mailbox: String,
}

/// Lifecycle of a queued archive command.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum OperationStatus {
    Queued,
    Applying,
    Confirmed,
    Failed,
    OutcomeUnknown,
}

/// Definite failure kinds. Cancelled work is not a failure; it is recovered.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(tag = "kind", rename_all = "snake_case")]
#[ts(rename_all = "snake_case")]
pub enum OperationFailure {
    ProviderUnavailable,
    ProviderRejected,
}

/// Durable acceptance proof for a command. Returned only after commit.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct OperationReceipt {
    pub operation_id: String,
    pub accepted_at: String,
}

/// Archive or unarchive one conversation, idempotent under `requestId`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct SetArchived {
    pub conversation: ConversationRef,
    pub archived: bool,
    pub request_id: String,
}

/// The two explicit mailbox setters; no arbitrary label execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum MailboxOperationKind {
    Archive,
    Read,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct SetRead {
    pub conversation: ConversationRef,
    pub read: bool,
    pub request_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct RetryOperation {
    pub operation_id: String,
    pub request_id: String,
}

/// One cached plain-text message.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct Message {
    pub id: String,
    pub from: Address,
    pub to: Vec<Address>,
    pub sent_at: String,
    /// Literal fixture text; hostile markup is data, never rendered.
    pub body_text: String,
}

/// Full conversation for the reader.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct Conversation {
    #[serde(rename = "ref")]
    pub conversation_ref: ConversationRef,
    pub subject: String,
    pub messages: Vec<Message>,
    /// Effective inbox membership (cached provider facts + pending overlay).
    pub is_in_inbox: bool,
    /// Absent when observed message read facts are unknown.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub is_read: Option<bool>,
    /// Gmail discloses whether the cached plain-text context is complete.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub context_complete: Option<bool>,
    /// Plain-text/format limitations. Absent for legacy fixture data.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub unsupported_reason: Option<String>,
    /// Local recovery snapshot capture time, not a provider freshness guarantee.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub retained_snapshot_at: Option<String>,
    /// Cached reply headers; absence never permits inferred recipients/threading.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub reply_context: Option<crate::drafts::types::ReplyContext>,
    /// Newest queued/applying operation id, if any.
    pub pending_operation_id: Option<String>,
}

/// One row of the conversation list.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct ConversationSummary {
    #[serde(rename = "ref")]
    pub conversation_ref: ConversationRef,
    pub subject: String,
    pub participants: Vec<Address>,
    /// Plain-text preview derived from the newest message body.
    pub preview: String,
    pub last_message_at: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub is_read: Option<bool>,
    pub pending_operation_id: Option<String>,
}

/// One persisted operation row for the activity surface.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct OperationSummary {
    pub id: String,
    pub conversation: ConversationRef,
    pub requested_archived: bool,
    pub status: OperationStatus,
    /// `null` unless the operation failed definitely.
    pub failure: Option<OperationFailure>,
    /// Absent kind is legacy fixture archive.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub kind: Option<MailboxOperationKind>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub requested_read: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub last_error: Option<crate::error::MailError>,
}

/// Inbox list plus full operation history for this fixture slice.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct InboxSnapshot {
    /// Conversations in the effective inbox, newest message first.
    pub conversations: Vec<ConversationSummary>,
    /// Persisted operations, newest acceptance first.
    pub activity: Vec<OperationSummary>,
}

/**
 * Frontend transport seam (Slices 01–04).
 *
 * The UI depends only on this interface. Two implementations exist:
 * - `tauri-client.ts`: narrow Tauri adapter over the approved named commands and the
 *   `mailbox_changed` event. Success values pass through; rejections are the typed
 *   MailError object emitted by the shell. The transport never invents success.
 * - `browser-fake.ts`: clearly labelled in-memory fake for browser preview and tests.
 *   It models core-like pending/failure behavior for demonstration only and discloses
 *   that nothing is durable. Core read models remain authoritative in the native path.
 *
 * Account lifecycle, mailbox actions, local drafts, and close requests cross only this
 * typed client seam; results never stand in for OAuth, sync, or provider-send success.
 */
import type {
  AccountStatus,
  AppCloseRequest,
  Conversation,
  ConversationRef,
  CreateDraft,
  DeleteDraft,
  Draft,
  DraftDeleteReceipt,
  DraftReceipt,
  DraftRef,
  DraftSummary,
  InboxSnapshot,
  MailError,
  OperationReceipt,
  RetryOperation,
  SaveDraft,
  SetArchived,
  SetRead,
} from './generated';

export type {
  AccountInfo,
  AccountStatus,
  AppCloseRequest,
  MailboxOperationKind,
  MutationAccess,
  Address,
  ConnectionState,
  Conversation,
  ConversationRef,
  ConversationSummary,
  CreateDraft,
  DeleteDraft,
  Draft,
  DraftContent,
  DraftDeleteReceipt,
  DraftReceipt,
  DraftRef,
  DraftSource,
  DraftReplyLink,
  DraftSummary,
  InboxSnapshot,
  MailError,
  MailMode,
  Message,
  OperationFailure,
  OperationReceipt,
  OperationStatus,
  RetryOperation,
  OperationSummary,
  SetArchived,
  SetRead,
  SaveDraft,
  ReplyContext,
  SyncInfo,
  SyncState,
} from './generated';

export {
  CANCEL_MAILBOX_ACTION_UPGRADE_COMMAND,
  CONNECT_ACCOUNT_COMMAND,
  DISCONNECT_ACCOUNT_COMMAND,
  GET_ACCOUNT_STATUS_COMMAND,
  GET_CONVERSATION_COMMAND,
  LIST_CONVERSATIONS_COMMAND,
  MAILBOX_CHANGED_EVENT,
  REQUEST_SYNC_COMMAND,
  SET_ARCHIVED_COMMAND,
  ENABLE_MAILBOX_ACTIONS_COMMAND,
  SET_READ_COMMAND,
  RETRY_OPERATION_COMMAND,
  LIST_DRAFTS_COMMAND,
  GET_DRAFT_COMMAND,
  CREATE_DRAFT_COMMAND,
  SAVE_DRAFT_COMMAND,
  DELETE_DRAFT_COMMAND,
  DRAFTS_CHANGED_EVENT,
  APP_CLOSE_REQUESTED_EVENT,
  GET_APP_CLOSE_REQUEST_COMMAND,
  COMPLETE_APP_CLOSE_COMMAND,
  CANCEL_APP_CLOSE_COMMAND,
} from './generated';

export interface MailClient {
  listConversations(): Promise<InboxSnapshot>;
  getConversation(ref: ConversationRef): Promise<Conversation>;
  setArchived(command: SetArchived): Promise<OperationReceipt>;
  enableMailboxActions(): Promise<void>;
  cancelMailboxActionUpgrade(): Promise<void>;
  setRead(command: SetRead): Promise<OperationReceipt>;
  retryOperation(command: RetryOperation): Promise<OperationReceipt>;
  /** Registers a change listener; resolves with an unsubscribe function. */
  subscribe(listener: () => void): Promise<() => void>;
  /** Authoritative fixture-vs-Gmail mode and connection/sync state. */
  getAccountStatus(): Promise<AccountStatus>;
  /** Enqueues a connect (OAuth) attempt; resolves on acceptance, not on success. */
  connectAccount(): Promise<void>;
  /** Resolves only after credentials and local account/cache data are cleared. */
  disconnectAccount(): Promise<void>;
  /** Enqueues an incremental sync; resolves on acceptance, not on completion. */
  requestSync(): Promise<void>;
  listDrafts(): Promise<DraftSummary[]>;
  getDraft(ref: DraftRef): Promise<Draft>;
  createDraft(command: CreateDraft): Promise<DraftReceipt>;
  saveDraft(command: SaveDraft): Promise<DraftReceipt>;
  deleteDraft(command: DeleteDraft): Promise<DraftDeleteReceipt>;
  subscribeDrafts(listener: () => void): Promise<() => void>;
  subscribeAppClose(listener: (request: AppCloseRequest) => void): Promise<() => void>;
  completeAppClose(requestId: string): Promise<void>;
  cancelAppClose(requestId: string): Promise<void>;
}

export function isMailErrorShape(value: unknown): value is MailError {
  if (typeof value !== 'object' || value === null || !('kind' in value)) return false;
  const kind = (value as { kind: unknown }).kind;
  if (typeof kind !== 'string') return false;
  switch (kind) {
    case 'not_found':
    case 'request_id_conflict':
    case 'storage_unavailable':
    case 'profile_in_use':
    case 'read_only':
    case 'not_configured':
    case 'auth_required':
    case 'auth_cancelled':
    case 'auth_failed':
    case 'secrets_unavailable':
    case 'network_unavailable':
    case 'rate_limited':
    case 'provider_unavailable':
    case 'invalid_provider_response':
    case 'busy':
    case 'permission_required':
    case 'provider_rejected':
    case 'outcome_unknown':
    case 'reply_unavailable':
      return true;
    case 'draft_conflict':
      return typeof (value as unknown as { currentRevision: unknown }).currentRevision === 'number';
    case 'invalid_request':
      return typeof (value as unknown as { field: unknown }).field === 'string';
    default:
      return false;
  }
}

/**
 * Normalizes a rejected command result into the MailError union. The native shell
 * rejects with the typed MailError object; anything else (native bug, serialization
 * gap) is conservatively surfaced as `storage_unavailable` rather than being
 * converted into a success or dropped.
 */
export function toMailError(raw: unknown): MailError {
  if (isMailErrorShape(raw)) return raw;
  return { kind: 'storage_unavailable' };
}

/* Local-only interface styles. No remote fonts, images, or CDN assets. */
:root {
  color-scheme: light dark;
  font-family: system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.app-header {
  border-bottom: 1px solid #8884;
  padding: 0.5rem 1rem;
}

.app-header h1 {
  font-size: 1rem;
  margin: 0 0 0.25rem;
}

.preview-banner {
  background: #fff3cd;
  color: #664d03;
  border: 1px solid #ffe08a;
  border-radius: 4px;
  padding: 0.25rem 0.5rem;
  margin: 0 0 0.25rem;
  font-size: 0.85rem;
}

.status-line {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  margin: 0;
}

.status-line [role='alert'] {
  color: #b02a37;
  font-weight: 600;
}

.app-main {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(0, 2fr) minmax(220px, 320px);
  gap: 1px;
  flex: 1;
  min-height: 0;
}

.list-pane,
.reader-pane,
.activity {
  overflow-y: auto;
  padding: 0.5rem;
  min-height: 0;
}

.inbox-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.inbox-row {
  border-bottom: 1px solid #8884;
  padding: 0.4rem 0.5rem;
  cursor: pointer;
}

.inbox-row.selected {
  background: highlight;
  color: highlighttext;
}

.row-top {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.8rem;
}

.row-subject {
  font-weight: 600;
  overflow-wrap: anywhere;
}

.row-preview,
.row-pending,
.row-subject,
.row-participants,
.row-time {
  overflow-wrap: anywhere;
}

.row-preview {
  font-size: 0.8rem;
  color: inherit;
  opacity: 0.8;
}

.row-pending {
  font-size: 0.75rem;
  font-style: italic;
}

.row-read-state {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.75rem;
}

.reader:focus {
  outline: none;
}

.reader-toolbar {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.reader-subject {
  font-size: 1.1rem;
  overflow-wrap: anywhere;
}

.reader-pending {
  font-style: italic;
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  border-top: 1px solid #8884;
  padding-top: 0.5rem;
  margin-bottom: 1rem;
}

.message-header {
  display: flex;
  gap: 0.75rem;
  font-size: 0.8rem;
  margin-bottom: 0.25rem;
  flex-wrap: wrap;
}

.message-body {
  white-space: pre-wrap;
  font-family: ui-monospace, monospace;
  font-size: 0.85rem;
  overflow-wrap: anywhere;
}

.activity-title {
  font-size: 0.9rem;
  margin: 0 0 0.5rem;
}

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.activity-row {
  border-bottom: 1px solid #8884;
  padding: 0.4rem 0;
  font-size: 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.status-queued,
.status-applying {
  font-style: italic;
}

.status-outcome_unknown,
.activity-warning,
.activity-error,
.account-action-error {
  color: #9a6700;
}

.activity-warning,
.activity-error {
  margin: 0;
}

.status-failed {
  color: #b02a37;
  font-weight: 600;
}

.activity-buttons {
  display: flex;
  gap: 0.4rem;
}

/* Local-only plain-text drafts; fields remain ordinary text controls. */
.drafts-pane {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(190px, 0.7fr) minmax(0, 2fr);
  gap: 0.8rem;
  max-height: 44vh;
  min-height: 0;
  overflow-y: auto;
  padding: 0.6rem;
  border-bottom: 1px solid #8884;
}

.draft-list,
.composer {
  min-width: 0;
}

.draft-list-heading,
.composer-heading,
.composer-actions,
.conflict-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.draft-list-heading h2,
.composer-heading h2 {
  font-size: 0.95rem;
  margin: 0.25rem 0;
}

.draft-local-note,
.reply-source,
.draft-status {
  margin: 0.3rem 0;
  font-size: 0.8rem;
  color: #7a5b00;
}

.draft-list ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.draft-row {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  padding: 0.4rem;
  border: 0;
  border-bottom: 1px solid #8884;
  background: transparent;
  color: inherit;
  text-align: left;
  overflow-wrap: anywhere;
}

.composer-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.composer-fields label {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 0.2rem;
  font-size: 0.85rem;
}

.composer-fields input,
.composer-fields textarea {
  width: 100%;
  min-width: 0;
  font: inherit;
}

.composer-fields textarea {
  min-height: 8rem;
  resize: vertical;
  white-space: pre-wrap;
  grid-column: 1 / -1;
}

.composer-fields label:has(textarea) {
  grid-column: 1 / -1;
}

@media (max-width: 760px) {
  .drafts-pane {
    grid-template-columns: 1fr;
    max-height: 55vh;
  }
}

/* Account gate, capability disclosures, and reader notices. */
.account-gate {
  padding: 1rem;
  color: #444;
}

.account-panel {
  border: 1px solid #8884;
  border-radius: 6px;
  padding: 0.6rem 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.85rem;
}

.account-row {
  display: flex;
  gap: 0.8rem;
  align-items: baseline;
}

.account-mode {
  font-weight: 600;
}

.account-connection {
  font-style: italic;
}

.account-email {
  margin: 0;
}

.account-notice {
  margin: 0;
  color: #7a5b00;
}

.account-sync-error {
  margin: 0;
  color: #b02a37;
  font-weight: 600;
}

.account-coverage,
.account-cached,
.account-disposable,
.account-upgrade-disclosure,
.account-disconnect-warning {
  margin: 0;
  color: #555;
}

.account-actions {
  display: flex;
  gap: 0.5rem;
}

.reader-notice,
.reader-readonly,
.reader-recovery-snapshot {
  margin: 0.2rem 0;
  color: #7a5b00;
  font-size: 0.85rem;
}

